      { t = "Aprende Minería con Messana Crestwind y Desuello con Mendalass Tattermend, en Shen'dar: dan oro para los entrenamientos. Compra el pico de minero y el cuchillo para desollar al vendedor de suministros de oficio, Belandiel Farflight. Mina cada veta de cobre y desuella todo lo que mates.", wp = { { m = 2521, z = "Isla Zephras", x = 44.8, y = 44.6, n = "Messana Crestwind", npc = 257022 }, { m = 2521, z = "Isla Zephras", x = 43.3, y = 43.4, n = "Mendalass Tattermend", npc = 257024 } }, comprobar = { oficios = { 186, 393 } } },
      { t = "Nivel 6: entrena con Corsan Earthrazer, en Shen'dar: Parada y Atronar. Aprende también Primeros auxilios con Naleeia Tattermend. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 2521, z = "Isla Zephras", x = 45.0, y = 45.1, n = "Corsan Earthrazer", npc = 254088 }, { m = 2521, z = "Isla Zephras", x = 43.1, y = 46.3, n = "Naleeia Tattermend", npc = 257018 } }, comprobar = { hechizos = { 3127 } } },
      { t = "Al oeste del pueblo mata videntes novicios de los Windshapers para [Una afrenta mágica]. Al norte, mata bandidos de las tierras altas y a su jefe, \"Badwind\" Bennic, para [El elemento criminal]: los bandidos sueltan las piedras de viento de [Piedras de viento robadas]. Los garrasorgullo del oeste dan las pieles de [El problema de los garrasorgullo].", wp = { { m = 2521, z = "Isla Zephras", x = 39.0, y = 47.1, n = "Objetivo: Una afrenta mágica", q = 94413, a = "C" }, { m = 2521, z = "Isla Zephras", x = 48.9, y = 37.0, n = "Objetivo: El elemento criminal", q = 92517, a = "C" }, { m = 2521, z = "Isla Zephras", x = 48.9, y = 37.0, n = "Objetivo: Piedras de viento robadas", q = 93319, a = "C" }, { m = 2521, z = "Isla Zephras", x = 42.5, y = 43.5, n = "Objetivo: El problema de los garrasorgullo", q = 92515, a = "C" } } },
      { t = "Vuelve a Shen'dar: entrega [Una afrenta mágica], [El elemento criminal], [Piedras de viento robadas] y [El problema de los garrasorgullo]. Constable Aonda te da [Infiltrarse en el culto]: entrégala a Sania Silverstream, al lado, y acepta [El pueblo de Falaath].", wp = { { m = 2521, z = "Isla Zephras", x = 45.0, y = 46.4, n = "Entregar: Una afrenta mágica (Rathiril Sunlance)", q = 94413, a = "T" }, { m = 2521, z = "Isla Zephras", x = 45.7, y = 45.5, n = "Entregar: El elemento criminal (Constable Aonda)", q = 92517, a = "T" }, { m = 2521, z = "Isla Zephras", x = 44.5, y = 45.0, n = "Entregar: Piedras de viento robadas (Teeri Wellwind)", q = 93319, a = "T" }, { m = 2521, z = "Isla Zephras", x = 44.7, y = 44.5, n = "Entregar: El problema de los garrasorgullo (Indari Sunseam)", q = 92515, a = "T" }, { m = 2521, z = "Isla Zephras", x = 45.7, y = 45.5, n = "Recoger: Infiltrarse en el culto (Constable Aonda)", q = 93036, a = "A" }, { m = 2521, z = "Isla Zephras", x = 44.9, y = 45.5, n = "Entregar: Infiltrarse en el culto (Sania Silverstream)", q = 93036, a = "T" }, { m = 2521, z = "Isla Zephras", x = 44.9, y = 45.5, n = "Recoger: El pueblo de Falaath (Sania Silverstream)", q = 92529, a = "A" } } },
      { t = "Al suroeste, mata crías y protectores de hipogrifo y a la matriarca para [Acoso de hipogrifos] y recoge el plumón de [Una pequeña belleza]. Por las tierras altas mata zancudos y coge huevos pequeños para [Llenar la despensa]. Al sur, junto al camino, vive Vulgara la Insaciable ([Se busca: Vulgara la Insaciable]).", wp = { { m = 2521, z = "Isla Zephras", x = 37.5, y = 53.8, n = "Objetivo: Acoso de hipogrifos", q = 92516, a = "C" }, { m = 2521, z = "Isla Zephras", x = 36.0, y = 53.2, n = "Objetivo: Una pequeña belleza", q = 93951, a = "C" }, { m = 2521, z = "Isla Zephras", x = 39.9, y = 54.3, n = "Objetivo: Llenar la despensa", q = 92553, a = "C" }, { m = 2521, z = "Isla Zephras", x = 42.7, y = 52.8, n = "Objetivo: Se busca: Vulgara la Insaciable", q = 93318, a = "C" } } },
      { t = "Vuelve a Shen'dar: entrega [Acoso de hipogrifos], [Una pequeña belleza], [Llenar la despensa] y [Se busca: Vulgara la Insaciable].", wp = { { m = 2521, z = "Isla Zephras", x = 44.5, y = 45.0, n = "Entregar: Acoso de hipogrifos (Teeri Wellwind)", q = 92516, a = "T" }, { m = 2521, z = "Isla Zephras", x = 44.9, y = 44.2, n = "Entregar: Una pequeña belleza (Taleen Shimmerthread)", q = 93951, a = "T" }, { m = 2521, z = "Isla Zephras", x = 43.9, y = 43.8, n = "Entregar: Llenar la despensa (Zerril Softbreeze)", q = 92553, a = "T" }, { m = 2521, z = "Isla Zephras", x = 45.2, y = 45.2, n = "Entregar: Se busca: Vulgara la Insaciable (Danarii Bellowveil)", q = 93318, a = "T" } } },
      { t = "Nivel 8: entrena con Corsan Earthrazer, en Shen'dar: Seccionar y Golpe heroico (rango 2). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 2521, z = "Isla Zephras", x = 45.0, y = 45.1, n = "Corsan Earthrazer", npc = 254088 } }, comprobar = { hechizos = { 1715 } } },
      { t = "Al sur, en la entrada del pueblo de Falaath, entrega [El pueblo de Falaath] a Missionary Jasaan y acepta [Entre los fieles]: recorre el pueblo para ver qué trama el culto.", wp = { { m = 2521, z = "Isla Zephras", x = 46.9, y = 56.2, n = "Entregar: El pueblo de Falaath (Missionary Jasaan)", q = 92529, a = "T" }, { m = 2521, z = "Isla Zephras", x = 46.9, y = 56.2, n = "Recoger: Entre los fieles (Missionary Jasaan)", q = 92528, a = "A" }, { m = 2521, z = "Isla Zephras", x = 48.8, y = 53.9, n = "Objetivo: Entre los fieles", q = 92528, a = "C" } } },
      { t = "Vuelve a Shen'dar: entrega [Entre los fieles] a Constable Aonda y acepta [Estragos en las tierras altas] y [La guardia del oeste]. Danarii Bellowveil te da [Suministros robados].", wp = { { m = 2521, z = "Isla Zephras", x = 45.7, y = 45.5, n = "Entregar: Entre los fieles (Constable Aonda)", q = 92528, a = "T" }, { m = 2521, z = "Isla Zephras", x = 45.7, y = 45.5, n = "Recoger: Estragos en las tierras altas (Constable Aonda)", q = 92550, a = "A" }, { m = 2521, z = "Isla Zephras", x = 45.7, y = 45.5, n = "Recoger: La guardia del oeste (Constable Aonda)", q = 93926, a = "A" }, { m = 2521, z = "Isla Zephras", x = 45.2, y = 45.2, n = "Recoger: Suministros robados (Danarii Bellowveil)", q = 92551, a = "A" } } },
      { t = "En el pueblo de Falaath mata invocatormentas Al'Aketh, relámpagos vivientes y al comandante Cyclas para [Estragos en las tierras altas], y coge los fardos robados de [Suministros robados].", wp = { { m = 2521, z = "Isla Zephras", x = 49.0, y = 55.7, n = "Objetivo: Estragos en las tierras altas", q = 92550, a = "C" }, { m = 2521, z = "Isla Zephras", x = 49.2, y = 55.9, n = "Objetivo: Suministros robados", q = 92551, a = "C" } } },
      { t = "Al oeste, en la torre de vigía, busca al pacificador Vaaniel ([La guardia del oeste]): entrégala, coge la nota que hay junto a él y léela ([Una última petición]).", wp = { { m = 2521, z = "Isla Zephras", x = 42.4, y = 62.0, n = "Entregar: La guardia del oeste (Peacekeeper Vaaniel)", q = 93926, a = "T" }, { m = 2521, z = "Isla Zephras", x = 42.4, y = 62.0, n = "Recoger: Una última petición (Peacekeeper Vaaniel)", q = 93927, a = "A" }, { m = 2521, z = "Isla Zephras", x = 41.7, y = 63.0, n = "Objetivo: Una última petición", q = 93927, a = "C" } } },
      { t = "Vuelve a Shen'dar: entrega [Estragos en las tierras altas], [Suministros robados] y [Una última petición]. Acepta [A Valanaar] y [Entrega el sello]: las dos se entregan en Valanaar, al sureste.", wp = { { m = 2521, z = "Isla Zephras", x = 45.7, y = 45.5, n = "Entregar: Estragos en las tierras altas (Constable Aonda)", q = 92550, a = "T" }, { m = 2521, z = "Isla Zephras", x = 45.2, y = 45.2, n = "Entregar: Suministros robados (Danarii Bellowveil)", q = 92551, a = "T" }, { m = 2521, z = "Isla Zephras", x = 45.7, y = 45.5, n = "Entregar: Una última petición (Constable Aonda)", q = 93927, a = "T" }, { m = 2521, z = "Isla Zephras", x = 45.7, y = 45.5, n = "Recoger: A Valanaar (Constable Aonda)", q = 92701, a = "A" }, { m = 2521, z = "Isla Zephras", x = 45.7, y = 45.5, n = "Recoger: Entrega el sello (Constable Aonda)", q = 93948, a = "A" } } },
      { t = "Misión extra en otra zona de tu nivel (Bosque de Elwynn): [Artículos rojos de lino] (nivel 9). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 79.5, y = 68.8, n = "Recoger: Artículos rojos de lino (Sara Timberlain)", q = 83, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 69.3, y = 79, n = "Bandidos Defias del huerto", q = 83, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 79.5, y = 68.8, n = "Entregar: Artículos rojos de lino (Sara Timberlain)", q = 83, a = "T" } } }, -- REFUERZO_97 q=83
      { t = "Misión extra para no quedarte corto de nivel: [Recompensas por los murlocs] (nivel 10). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 74, y = 72.2, n = "Recoger: Recompensas por los murlocs (Guardia Thomas)", q = 46, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 74, y = 72.2, n = "Entregar: Recompensas por los murlocs (Guardia Thomas)", q = 46, a = "T" } } }, -- REFUERZO_97 q=46
      { t = "Misión extra en otra zona de tu nivel (Dun Morogh): [Operación Recombobulador] (nivel 10). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1426, z = "Dun Morogh", x = 45.9, y = 49.4, n = "Recoger: Operación Recombobulador (Razzle Energiodentado)", q = 412, a = "A" }, { m = 1426, z = "Dun Morogh", x = 26, y = 40.3, n = "Objetivo: Operación Recombobulador", q = 412, a = "C" }, { m = 1426, z = "Dun Morogh", x = 45.9, y = 49.4, n = "Entregar: Operación Recombobulador (Razzle Energiodentado)", q = 412, a = "T" } } }, -- REFUERZO_97 q=412
    },
  },
  {
    titulo = "Isla Zephras: Valanaar y las Tierras Bajas", min = 8, max = 10,
    entrenar = "Instructora de guerrero en Valanaar: Seena Skybreaker. Al 10 aprende Ira sangrienta y Desgarrar (rango 2), y ella misma te da tu misión de clase: [El Baluarte Skybreaker], que te enseña Actitud defensiva, Provocar y Hender armadura.",
    equipo = "En Valanaar hay herrero (Daeann Steelwind) y subasta: un arma de dos manos mejor es tu mayor mejora.",
    profesion = "En Valanaar hay instructores de todas las profesiones, banco (Baelann Favorbreeze) y subasta (Zelena Favorbreeze). Primeros auxilios con Melasa Fairmend.",
    pasos = {
      { t = "Sigue el camino al sureste. A medio camino, Fendaal Windstone te da [Asesinos Al'Aketh]: mata asesinos Al'Aketh a su alrededor y entrégala.", wp = { { m = 2521, z = "Isla Zephras", x = 56.8, y = 61.1, n = "Recoger: Asesinos Al'Aketh (Fendaal Windstone)", q = 98512, a = "A" }, { m = 2521, z = "Isla Zephras", x = 55.9, y = 60.6, n = "Objetivo: Asesinos Al'Aketh", q = 98512, a = "C" }, { m = 2521, z = "Isla Zephras", x = 56.8, y = 61.1, n = "Entregar: Asesinos Al'Aketh (Fendaal Windstone)", q = 98512, a = "T" } } },
      { t = "En Valanaar entrega [A Valanaar] a Valennia Stormfist y [Entrega el sello] a Talaanis Shadowsong. Pon la piedra de hogar con Donaal Downbreeze. Valennia Stormfist te da [La Magistrada Suprema] y [Bichos]; Alvarion Windfield te da [Diezmo de sangre].", wp = { { m = 2521, z = "Isla Zephras", x = 66.1, y = 76.7, n = "Entregar: A Valanaar (Valennia Stormfist)", q = 92701, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 76.5, n = "Entregar: Entrega el sello (Talaanis Shadowsong)", q = 93948, a = "T" }, { m = 2521, z = "Isla Zephras", x = 62.2, y = 72.6, n = "Donaal Downbreeze", npc = 255940 }, { m = 2521, z = "Isla Zephras", x = 66.1, y = 76.7, n = "Recoger: La Magistrada Suprema (Valennia Stormfist)", q = 92699, a = "A" }, { m = 2521, z = "Isla Zephras", x = 66.1, y = 76.7, n = "Recoger: Bichos (Valennia Stormfist)", q = 93949, a = "A" }, { m = 2521, z = "Isla Zephras", x = 62.1, y = 73.2, n = "Recoger: Diezmo de sangre (Alvarion Windfield)", q = 92679, a = "A" } } },
      { t = "Mata saltacielos encantados por Valanaar para [Bichos] y entrégala.", wp = { { m = 2521, z = "Isla Zephras", x = 62.0, y = 76.0, n = "Objetivo: Bichos", q = 93949, a = "C" }, { m = 2521, z = "Isla Zephras", x = 66.1, y = 76.7, n = "Entregar: Bichos (Valennia Stormfist)", q = 93949, a = "T" } } },
      { t = "Busca a Elaadrin Evengale, en Valanaar: entrégala y acepta [Una gran aventura]: escúchala y entrégala. Dondallion Whisperwind, a su lado, te da [El erudito desaparecido].", wp = { { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Entregar: La Magistrada Suprema (Elaadrin Evengale)", q = 92699, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Recoger: Una gran aventura (Elaadrin Evengale)", q = 92709, a = "A" }, { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Objetivo: Una gran aventura", q = 92709, a = "C" }, { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Entregar: Una gran aventura (Elaadrin Evengale)", q = 92709, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.3, y = 79.8, n = "Recoger: El erudito desaparecido (Dondallion Whisperwind)", q = 92727, a = "A" } } },
      { t = "Al oeste, en el huerto de los Windfield, entrega [Diezmo de sangre] a Aamelia Windfield y acepta [Hazte útil], [Polvo de mariposa] y [Galestriders ariscos]. El autómata averiado, al lado, te da [¿Cuál es mi propósito?]: entrégala a Aamelia Windfield.", wp = { { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Entregar: Diezmo de sangre (Aamelia Windfield)", q = 92679, a = "T" }, { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Recoger: Hazte útil (Aamelia Windfield)", q = 92682, a = "A" }, { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Recoger: Polvo de mariposa (Aamelia Windfield)", q = 92683, a = "A" }, { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Recoger: Galestriders ariscos (Aamelia Windfield)", q = 92684, a = "A" }, { m = 2521, z = "Isla Zephras", x = 48.9, y = 78.2, n = "Recoger: ¿Cuál es mi propósito? (Autómata ciclónico averiado)", q = 92698, a = "A" }, { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Entregar: ¿Cuál es mi propósito? (Aamelia Windfield)", q = 92698, a = "T" } } },
      { t = "Por las Tierras Bajas de Gustberry: recoge manzanas de tormenta y mata bandidos hambrientos para [Hazte útil], mariposas por el polvo de [Polvo de mariposa] y galestriders ariscos por los solomillos de [Galestriders ariscos].", wp = { { m = 2521, z = "Isla Zephras", x = 47.9, y = 80.8, n = "Objetivo: Hazte útil", q = 92682, a = "C" }, { m = 2521, z = "Isla Zephras", x = 50.3, y = 78.8, n = "Objetivo: Polvo de mariposa", q = 92683, a = "C" }, { m = 2521, z = "Isla Zephras", x = 51.9, y = 76.7, n = "Objetivo: Galestriders ariscos", q = 92684, a = "C" } } },
      { t = "Entrégalas a Aamelia Windfield y acepta [Las colinas tienen ojos]: mata salteadores por las máscaras manchadas de sangre. Entrégala y acepta [Defender nuestra tierra]: habla con ella cuando estés listo y vence al jefe de los bandidos. Entrégala y acepta [Lleva la noticia].", wp = { { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Entregar: Hazte útil (Aamelia Windfield)", q = 92682, a = "T" }, { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Entregar: Polvo de mariposa (Aamelia Windfield)", q = 92683, a = "T" }, { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Entregar: Galestriders ariscos (Aamelia Windfield)", q = 92684, a = "T" }, { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Recoger: Las colinas tienen ojos (Aamelia Windfield)", q = 92685, a = "A" }, { m = 2521, z = "Isla Zephras", x = 48.5, y = 75.4, n = "Objetivo: Las colinas tienen ojos", q = 92685, a = "C" }, { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Entregar: Las colinas tienen ojos (Aamelia Windfield)", q = 92685, a = "T" }, { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Recoger: Defender nuestra tierra (Aamelia Windfield)", q = 92693, a = "A" }, { m = 2521, z = "Isla Zephras", x = 47.9, y = 78.4, n = "Objetivo: Defender nuestra tierra", q = 92693, a = "C" }, { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Entregar: Defender nuestra tierra (Aamelia Windfield)", q = 92693, a = "T" }, { m = 2521, z = "Isla Zephras", x = 46.7, y = 82.0, n = "Recoger: Lleva la noticia (Aamelia Windfield)", q = 92703, a = "A" } } },
      { t = "Vuelve a Valanaar y entrega [Lleva la noticia] a Alvarion Windfield.", wp = { { m = 2521, z = "Isla Zephras", x = 62.1, y = 73.2, n = "Entregar: Lleva la noticia (Alvarion Windfield)", q = 92703, a = "T" } } },
      { t = "Al suroeste de Valanaar, en las Tierras Bajas de Gustberry, busca a Fillion ([El erudito desaparecido]): en su campamento abandonado empieza [El erudito desaparecido]. Sigue su rastro hacia el norte y habla con él; entrégala a Fillion Flamebreeze y acepta [El erudito desaparecido].", wp = { { m = 2521, z = "Isla Zephras", x = 53.3, y = 72.2, n = "Entregar: El erudito desaparecido (Bloodstained Satchel)", q = 92727, a = "T" }, { m = 2521, z = "Isla Zephras", x = 53.3, y = 72.2, n = "Recoger: El erudito desaparecido (Bloodstained Satchel)", q = 92849, a = "A" }, { m = 2521, z = "Isla Zephras", x = 50.9, y = 66.9, n = "Objetivo: El erudito desaparecido", q = 92849, a = "C" }, { m = 2521, z = "Isla Zephras", x = 52.1, y = 69.4, n = "Entregar: El erudito desaparecido (Fillion Flamebreeze)", q = 92849, a = "T" }, { m = 2521, z = "Isla Zephras", x = 52.1, y = 69.4, n = "Recoger: El erudito desaparecido (Fillion Flamebreeze)", q = 92850, a = "A" } } },
      { t = "Al lado, en la Guarida de los chillones, mata a la matriarca chillona y coge su cabeza ([El erudito desaparecido]). Vuelve a Valanaar: entrégala a Fillion Flamebreeze y acepta [La misión de Fillion]; entrégala a Elaadrin Evengale y acepta [Atrapar el viento].", wp = { { m = 2521, z = "Isla Zephras", x = 52.4, y = 65.9, n = "Objetivo: El erudito desaparecido", q = 92850, a = "C" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 79.9, n = "Entregar: El erudito desaparecido (Fillion Flamebreeze)", q = 92850, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 79.9, n = "Recoger: La misión de Fillion (Fillion Flamebreeze)", q = 99260, a = "A" }, { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Entregar: La misión de Fillion (Elaadrin Evengale)", q = 99260, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Recoger: Atrapar el viento (Elaadrin Evengale)", q = 92840, a = "A" } } },
      { t = "Al oeste, en las piedras del mirador de las Tierras Altas de Shen'dar, usa el Índice esotérico en las formaciones de piedra de viento ([Atrapar el viento]). Vuelve con Elaadrin Evengale: entrégala y acepta [Al servicio de Zephras] y [Vengados diez veces].", wp = { { m = 2521, z = "Isla Zephras", x = 47.0, y = 69.0, n = "Formaciones de piedra de viento", q = 92840, a = "C" }, { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Entregar: Atrapar el viento (Elaadrin Evengale)", q = 92840, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Recoger: Al servicio de Zephras (Elaadrin Evengale)", q = 92860, a = "A" }, { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Recoger: Vengados diez veces (Elaadrin Evengale)", q = 92834, a = "A" } } },
      { t = "Entrega [Al servicio de Zephras] a Valennia Stormfist y acepta [Defensa de la torre]: ve a la torre de vigía del este y entrégala a Yorana Windyreed. Acepta [Cortar los suministros] y [Romper al Rompedor].", wp = { { m = 2521, z = "Isla Zephras", x = 66.1, y = 76.7, n = "Entregar: Al servicio de Zephras (Valennia Stormfist)", q = 92860, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.1, y = 76.7, n = "Recoger: Defensa de la torre (Valennia Stormfist)", q = 93320, a = "A" }, { m = 2521, z = "Isla Zephras", x = 69.7, y = 67.1, n = "Entregar: Defensa de la torre (Yorana Windyreed)", q = 93320, a = "T" }, { m = 2521, z = "Isla Zephras", x = 69.7, y = 67.1, n = "Recoger: Cortar los suministros (Yorana Windyreed)", q = 92642, a = "A" }, { m = 2521, z = "Isla Zephras", x = 69.7, y = 67.1, n = "Recoger: Romper al Rompedor (Yorana Windyreed)", q = 92645, a = "A" } } },
      { t = "Alrededor de la torre mata sanadores y camorristas Al'Aketh para [Cortar los suministros] y al comandante Belguilos para [Romper al Rompedor]. Los cultistas Al'Aketh sueltan los amuletos de [Vengados diez veces]. Entrega [Cortar los suministros] y [Romper al Rompedor] y acepta [Vuelve a Valanaar].", wp = { { m = 2521, z = "Isla Zephras", x = 65.9, y = 67.5, n = "Objetivo: Cortar los suministros", q = 92642, a = "C" }, { m = 2521, z = "Isla Zephras", x = 65.6, y = 65.6, n = "Objetivo: Romper al Rompedor", q = 92645, a = "C" }, { m = 2521, z = "Isla Zephras", x = 63.7, y = 65.3, n = "Objetivo: Vengados diez veces", q = 92834, a = "C" }, { m = 2521, z = "Isla Zephras", x = 69.7, y = 67.1, n = "Entregar: Cortar los suministros (Yorana Windyreed)", q = 92642, a = "T" }, { m = 2521, z = "Isla Zephras", x = 69.7, y = 67.1, n = "Entregar: Romper al Rompedor (Yorana Windyreed)", q = 92645, a = "T" }, { m = 2521, z = "Isla Zephras", x = 69.7, y = 67.1, n = "Recoger: Vuelve a Valanaar (Yorana Windyreed)", q = 92880, a = "A" } } },
      { t = "Vuelve a Valanaar: entrega [Vuelve a Valanaar] a Valennia Stormfist y acepta [La petición de la Alta Anciana]: entrégala a Talaanis Shadowsong y acepta [El traidor]. Entrega [Vengados diez veces] a Elaadrin Evengale.", wp = { { m = 2521, z = "Isla Zephras", x = 66.1, y = 76.7, n = "Entregar: Vuelve a Valanaar (Valennia Stormfist)", q = 92880, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.1, y = 76.7, n = "Recoger: La petición de la Alta Anciana (Valennia Stormfist)", q = 92881, a = "A" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 76.5, n = "Entregar: La petición de la Alta Anciana (Talaanis Shadowsong)", q = 92881, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 76.5, n = "Recoger: El traidor (Talaanis Shadowsong)", q = 92643, a = "A" }, { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Entregar: Vengados diez veces (Elaadrin Evengale)", q = 92834, a = "T" } } },
      { t = "Nivel 10: entrena con Seena Skybreaker, en Valanaar: Ira sangrienta y Desgarrar (rango 2). Acepta su misión de clase, [El Baluarte Skybreaker]. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 2521, z = "Isla Zephras", x = 59.9, y = 72.9, n = "Seena Skybreaker", npc = 252377 }, { m = 2521, z = "Isla Zephras", x = 59.9, y = 72.9, n = "Recoger: El Baluarte Skybreaker (Seena Skybreaker)", q = 94003, a = "A" } }, comprobar = { hechizos = { 2687 } } },
      { t = "Misión extra en otra zona de tu nivel (Bosque de Elwynn): [Proteger la frontera] (nivel 10). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 74, y = 72.2, n = "Recoger: Proteger la frontera (Guardia Thomas)", q = 52, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 78.5, y = 79.3, n = "Objetivo: Proteger la frontera", q = 52, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 74, y = 72.2, n = "Entregar: Proteger la frontera (Guardia Thomas)", q = 52, a = "T" } } }, -- REFUERZO_97 q=52
      { t = "Misión extra en otra zona de tu nivel (Dun Morogh): [La protección del rebaño] (nivel 12). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1426, z = "Dun Morogh", x = 63.1, y = 49.9, n = "Recoger: La protección del rebaño", q = 314, a = "A" }, { m = 1426, z = "Dun Morogh", x = 62.6, y = 46.0, n = "Objetivo: La protección del rebaño", q = 314, a = "C" }, { m = 1426, z = "Dun Morogh", x = 63.1, y = 49.9, n = "Entregar: La protección del rebaño", q = 314, a = "T" } } }, -- REFUERZO_97 q=314
    },
  },
  {
    titulo = "Isla Zephras: el Bosque Shadowgale y el Santuario de Akir", min = 10, max = 13,
    entrenar = "Primer talento al 10: Armas > Desgarrar mejorado. Al 12, en Ventormenta: Abrumar y Grito de batalla (rango 2).",
    equipo = "Las misiones del santuario dan buenas piezas para tu nivel.",
    profesion = "Los animales del Bosque Shadowgale dan cuero ligero; las vetas de cobre están en las colinas.",
    pasos = {
      { t = "Al noroeste de Valanaar, en la casa que hay al entrar en las tierras altas, examina al cultista muerto ([El traidor]) y acepta [Malas noticias]. Vuelve a Valanaar: entrégala a Talaanis Shadowsong y acepta [Los verdaderos planes del culto]: escucha la conversación y entrégala. Acepta [Tiempos desesperados].", wp = { { m = 2521, z = "Isla Zephras", x = 56.0, y = 58.8, n = "Entregar: El traidor (Cultista muerto)", q = 92643, a = "T" }, { m = 2521, z = "Isla Zephras", x = 56.0, y = 58.8, n = "Recoger: Malas noticias (Cultista muerto)", q = 92644, a = "A" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 76.5, n = "Entregar: Malas noticias (Talaanis Shadowsong)", q = 92644, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 76.5, n = "Recoger: Los verdaderos planes del culto (Talaanis Shadowsong)", q = 94568, a = "A" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 76.5, n = "Objetivo: Los verdaderos planes del culto", q = 94568, a = "C" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 76.5, n = "Entregar: Los verdaderos planes del culto (Talaanis Shadowsong)", q = 94568, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 76.5, n = "Recoger: Tiempos desesperados (Talaanis Shadowsong)", q = 92640, a = "A" } } },
      { t = "Si Lotheluum Starbreeze te ofrece [Un silencio inquietante] en Valanaar, acéptala. Acepta también [Visitas indeseadas] (Iaadaria Bitterwind) y [Ayuda para los refugiados] y [El destino de un ser querido] (Ealaane Nimbuswalker).", wp = { { m = 2521, z = "Isla Zephras", x = 64.0, y = 75.1, n = "Recoger: Un silencio inquietante (Lotheluum Starbreeze)", q = 94484, a = "A", alternativa = 94493 }, { m = 2521, z = "Isla Zephras", x = 66.3, y = 79.5, n = "Recoger: Visitas indeseadas (Iaadaria Bitterwind)", q = 92741, a = "A" }, { m = 2521, z = "Isla Zephras", x = 66.0, y = 74.4, n = "Recoger: Ayuda para los refugiados (Ealaane Nimbuswalker)", q = 94896, a = "A" }, { m = 2521, z = "Isla Zephras", x = 66.0, y = 74.4, n = "Recoger: El destino de un ser querido (Ealaane Nimbuswalker)", q = 94897, a = "A" } } },
      { t = "Al norte, en el Bosque Shadowgale, habla con Elegael Thornpaw. Si llevas [Un silencio inquietante], entrégala. Si Elegael te ofrece en su lugar [Un sacrificio en vano], escúchala y entrégala. Cuando completes una de las dos, acepta [Lágrimas de la Dama], [Plumas para atar] y [Indeseados e indignos]. Vayn Moongaze, al lado, te da [La piedad cae en oídos sordos].", wp = { { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Entregar: Un silencio inquietante (Elegael Thornpaw)", q = 94484, a = "T", alternativa = 94493 }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Recoger: Un sacrificio en vano (Elegael Thornpaw)", q = 94493, a = "A", alternativa = 94484 }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Entregar: Un sacrificio en vano (Elegael Thornpaw)", q = 94493, a = "T", alternativa = 94484 }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Recoger: Lágrimas de la Dama (Elegael Thornpaw)", q = 94485, a = "A" }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Recoger: Plumas para atar (Elegael Thornpaw)", q = 94486, a = "A" }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Recoger: Indeseados e indignos (Elegael Thornpaw)", q = 94487, a = "A" }, { m = 2521, z = "Isla Zephras", x = 63.8, y = 36.0, n = "Recoger: La piedad cae en oídos sordos (Vayn Moongaze)", q = 93165, a = "A" } } },
      { t = "Por el bosque: musgo lágrima de la Dama para [Lágrimas de la Dama], plumas de los chillones para [Plumas para atar] y reliquias de los soldados y cazatormentas Al'Aketh para [Indeseados e indignos]; los cultistas te dan también las orejas de [La piedad cae en oídos sordos]. Los chillones sueltan también las garras de [Visitas indeseadas]. En las ruinas de Ban'aethal recoge las pertenencias de [Ayuda para los refugiados] y busca a Resaan ([El destino de un ser querido]).", wp = { { m = 2521, z = "Isla Zephras", x = 60.9, y = 38.4, n = "Objetivo: Lágrimas de la Dama", q = 94485, a = "C" }, { m = 2521, z = "Isla Zephras", x = 59.3, y = 38.7, n = "Objetivo: Plumas para atar", q = 94486, a = "C" }, { m = 2521, z = "Isla Zephras", x = 63.5, y = 37.3, n = "Objetivo: Indeseados e indignos", q = 94487, a = "C" }, { m = 2521, z = "Isla Zephras", x = 63.2, y = 50.3, n = "Objetivo: La piedad cae en oídos sordos", q = 93165, a = "C" }, { m = 2521, z = "Isla Zephras", x = 59.0, y = 39.1, n = "Objetivo: Visitas indeseadas", q = 92741, a = "C" }, { m = 2521, z = "Isla Zephras", x = 58.0, y = 31.9, n = "Objetivo: Ayuda para los refugiados", q = 94896, a = "C" }, { m = 2521, z = "Isla Zephras", x = 57.0, y = 29.4, n = "Objetivo: El destino de un ser querido", q = 94897, a = "C" } } },
      { t = "Vuelve con Elegael Thornpaw: entrega [Lágrimas de la Dama], [Plumas para atar] y [Indeseados e indignos], y acepta [Los lazos que unen] y [Las heridas de la traición]. Entrega [La piedad cae en oídos sordos] a Vayn Moongaze y acepta [Más orejas Al'Aketh].", wp = { { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Entregar: Lágrimas de la Dama (Elegael Thornpaw)", q = 94485, a = "T" }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Entregar: Plumas para atar (Elegael Thornpaw)", q = 94486, a = "T" }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Entregar: Indeseados e indignos (Elegael Thornpaw)", q = 94487, a = "T" }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Recoger: Los lazos que unen (Elegael Thornpaw)", q = 94488, a = "A" }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Recoger: Las heridas de la traición (Elegael Thornpaw)", q = 94489, a = "A" }, { m = 2521, z = "Isla Zephras", x = 63.8, y = 36.0, n = "Entregar: La piedad cae en oídos sordos (Vayn Moongaze)", q = 93165, a = "T" }, { m = 2521, z = "Isla Zephras", x = 63.8, y = 36.0, n = "Recoger: Más orejas Al'Aketh (Vayn Moongaze)", q = 93459, a = "A" } } },
      { t = "Al este mata al comandante Haalien ([Los lazos que unen]). En la Guarida Colmillo Nocturno cura a 7 druidas y busca a Jorel Windsinger ([Las heridas de la traición]); coge el mensaje roto que hay dentro ([Un mensaje roto]). Junta más orejas de cultista para [Más orejas Al'Aketh].", wp = { { m = 2521, z = "Isla Zephras", x = 65.5, y = 36.3, n = "Objetivo: Los lazos que unen", q = 94488, a = "C" }, { m = 2521, z = "Isla Zephras", x = 64.9, y = 33.7, n = "Objetivo: Las heridas de la traición", q = 94489, a = "C" }, { m = 2521, z = "Isla Zephras", x = 64.9, y = 33.7, n = "Mensaje roto (Guarida Colmillo Nocturno)", q = 94490, a = "A" }, { m = 2521, z = "Isla Zephras", x = 63.2, y = 50.3, n = "Objetivo: Más orejas Al'Aketh", q = 93459, a = "C" } } },
      { t = "Entrega [Los lazos que unen], [Las heridas de la traición] y [Un mensaje roto] y acepta [El destino de la guarida]. Entrega [Más orejas Al'Aketh] a Vayn Moongaze.", wp = { { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Entregar: Los lazos que unen (Elegael Thornpaw)", q = 94488, a = "T" }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Entregar: Las heridas de la traición (Elegael Thornpaw)", q = 94489, a = "T" }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Entregar: Un mensaje roto (Elegael Thornpaw)", q = 94490, a = "T" }, { m = 2521, z = "Isla Zephras", x = 61.7, y = 39.2, n = "Recoger: El destino de la guarida (Elegael Thornpaw)", q = 94491, a = "A" }, { m = 2521, z = "Isla Zephras", x = 63.8, y = 36.0, n = "Entregar: Más orejas Al'Aketh (Vayn Moongaze)", q = 93459, a = "T" } } },
      { t = "Vuelve a Valanaar: entrega [El destino de la guarida] a Lotheluum Starbreeze, [Visitas indeseadas] a Iaadaria Bitterwind y [Ayuda para los refugiados] y [El destino de un ser querido] a Ealaane Nimbuswalker. Entrega [Tiempos desesperados] a Valennia Stormfist y acepta [Preparados para la batalla].", wp = { { m = 2521, z = "Isla Zephras", x = 64.0, y = 75.1, n = "Entregar: El destino de la guarida (Lotheluum Starbreeze)", q = 94491, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.3, y = 79.5, n = "Entregar: Visitas indeseadas (Iaadaria Bitterwind)", q = 92741, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.0, y = 74.4, n = "Entregar: Ayuda para los refugiados (Ealaane Nimbuswalker)", q = 94896, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.0, y = 74.4, n = "Entregar: El destino de un ser querido (Ealaane Nimbuswalker)", q = 94897, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.1, y = 76.7, n = "Entregar: Tiempos desesperados (Valennia Stormfist)", q = 92640, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.1, y = 76.7, n = "Recoger: Preparados para la batalla (Valennia Stormfist)", q = 93065, a = "A" } } },
      { t = "Al norte de Valanaar entrega [Preparados para la batalla] a Valennia Stormfist y acepta [Nuestro movimiento]: en el Santuario de Akir mata guardianes, invocaespíritus y maestros de espadas Al'Aketh y entrégala a Hyusaa Quickbreeze. Acepta [El sanctasanctórum] y entrégala a Valennia Stormfist, en el sanctasanctórum.", wp = { { m = 2521, z = "Isla Zephras", x = 61.2, y = 70.9, n = "Entregar: Preparados para la batalla (Valennia Stormfist)", q = 93065, a = "T" }, { m = 2521, z = "Isla Zephras", x = 61.2, y = 70.9, n = "Recoger: Nuestro movimiento (Valennia Stormfist)", q = 92947, a = "A" }, { m = 2521, z = "Isla Zephras", x = 62.2, y = 50.6, n = "Objetivo: Nuestro movimiento", q = 92947, a = "C" }, { m = 2521, z = "Isla Zephras", x = 63.8, y = 50.5, n = "Entregar: Nuestro movimiento (Hyusaa Quickbreeze)", q = 92947, a = "T" }, { m = 2521, z = "Isla Zephras", x = 63.8, y = 50.5, n = "Recoger: El sanctasanctórum (Hyusaa Quickbreeze)", q = 93958, a = "A" }, { m = 2521, z = "Isla Zephras", x = 65.2, y = 50.4, n = "Entregar: El sanctasanctórum (Valennia Stormfist)", q = 93958, a = "T" } } },
      { t = "Al oeste del Santuario de Akir, quítale el Baluarte Skybreaker a Zaal Stormshield ([El Baluarte Skybreaker]).", wp = { { m = 2521, z = "Isla Zephras", x = 56.6, y = 50.4, n = "Objetivo: El Baluarte Skybreaker", q = 94003, a = "C" } } },
      { t = "Valennia Stormfist te da [Enfrentarse a Lorthuna]: coge el portal a las Agujas de Rohashi y vence a la Suma Sacerdotisa Lorthuna con Elaadrin y Ayessa. Vuelve a Valanaar: entrega [Enfrentarse a Lorthuna] a Elaadrin Evengale y acepta [El destino de Zephras]; entrégala a Talaanis Shadowsong y acepta [Lo que viene después].", wp = { { m = 2521, z = "Isla Zephras", x = 65.2, y = 50.4, n = "Recoger: Enfrentarse a Lorthuna (Valennia Stormfist)", q = 93835, a = "A" }, { m = 2521, z = "Isla Zephras", x = 74.6, y = 53.8, n = "Agujas de Rohashi", q = 93835, a = "C" }, { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Entregar: Enfrentarse a Lorthuna (Elaadrin Evengale)", q = 93835, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.6, y = 79.9, n = "Recoger: El destino de Zephras (Elaadrin Evengale)", q = 94369, a = "A" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 76.5, n = "Entregar: El destino de Zephras (Talaanis Shadowsong)", q = 94369, a = "T" }, { m = 2521, z = "Isla Zephras", x = 66.2, y = 76.5, n = "Recoger: Lo que viene después (Talaanis Shadowsong)", q = 93089, a = "A" } } },
      { t = "Entrega [El Baluarte Skybreaker] a Seena Skybreaker, en Valanaar: aprendes Actitud defensiva, Provocar y Hender armadura.", wp = { { m = 2521, z = "Isla Zephras", x = 59.9, y = 72.9, n = "Entregar: El Baluarte Skybreaker (Seena Skybreaker)", q = 94003, a = "T" } } },
