  {
    titulo = "Forjaz y Loch Modan", min = 15, max = 16,
    entrenar = "En Ventormenta haz tu misión de clase: vencer a Bartleby, en el Casco Antiguo, te da Actitud defensiva, Provocar y Hender armadura. Instructores de guerrero: Wu Shen en los barracones del Casco Antiguo y, en el Barrio Militar de Forjaz, Kelstrum Rompepedras y Kelv Martillodusto. Talento: Desgarrar mejorado hasta el 12.",
    equipo = "La cadena sigue en Forjaz con [Tormus Forjahonda] y acaba en [Armas de hierro gris]: un arma de una mano a elegir. Si ya llevas una de dos manos con más daño, quédate con la tuya y vende la nueva. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Minería y Desuello a 50: rango oficial con Gelman Petramano y Maris Granger en Ventormenta, o con Geofram Dedorroca y Balthus Cazarrocas en Forjaz. Primeros auxilios con Shaina Fuller, en la Plaza de la Catedral: <Venda de lino>.",
    pasos = {
      { t = "Vuela de la Colina del Centinela a Ventormenta con Thor.", wp = { { m = 1436, z = "Páramos de Poniente", x = 56.5, y = 52.6, n = "Thor", npc = 523 } } },
      { t = "Misión extra para no quedarte corto de nivel: [Las Milicias del Pueblo] (nivel 17). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1436, z = "Páramos de Poniente", x = 56.3, y = 47.5, n = "Recoger: Las Milicias del Pueblo (Gryan Mantorrecio)", q = 14, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 46.4, y = 78.3, n = "Objetivo: Las Milicias del Pueblo", q = 14, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 56.3, y = 47.5, n = "Entregar: Las Milicias del Pueblo (Gryan Mantorrecio)", q = 14, a = "T" } } }, -- REFUERZO_97 q=14
      { t = "En el Distrito de los Enanos coge el Tranvía Subterráneo a Forjaz y activa el vuelo con Gryth Thurden en la Gran Herrería: lo usarás para venir a entrenar.", wp = { { m = 1455, z = "Forjaz", x = 55.5, y = 47.7, n = "Gryth Thurden", npc = 1573 } }, comprobar = { vuelo = "Forjaz" } },
      { t = "Barrio Militar: Muren Pico Tormenta te da [Tormus Forjahonda]. Si aún no sabes usar hachas o mazas de dos manos, apréndelas allí con Buliwyf Petramano. Lleva [Tormus Forjahonda] a Tormus Forjahonda, en la Gran Herrería, y acepta [Complejo Vetaferro].", wp = { { m = 1455, z = "Forjaz", x = 70.8, y = 90.3, n = "Recoger: Tormus Forjahonda (Muren Pico Tormenta)", q = 1680, a = "A" }, { m = 1455, z = "Forjaz", x = 61.2, y = 89.5, n = "Buliwyf Petramano", npc = 11865 }, { m = 1455, z = "Forjaz", x = 48.6, y = 42.5, n = "Entregar: Tormus Forjahonda (Tormus Forjahonda)", q = 1680, a = "T" }, { m = 1455, z = "Forjaz", x = 48.6, y = 42.5, n = "Recoger: Complejo Vetaferro (Tormus Forjahonda)", q = 1681, a = "A" } } },
      { t = "Sal de Forjaz hacia el este por Dun Morogh. Cantera de Gol'Bolar: [¡Malditos troggs!] y [El servidor público].", wp = { { m = 1426, z = "Dun Morogh", x = 69.1, y = 56.3, n = "Recoger: ¡Malditos troggs! (Supervisor Petrocejas)", q = 432, a = "A" }, { m = 1426, z = "Dun Morogh", x = 68.7, y = 56.0, n = "Recoger: El servidor público (Senador Mehr Piedrasanta)", q = 433, a = "A" }, { m = 1426, z = "Dun Morogh", x = 70.3, y = 55.9, n = "Objetivo: ¡Malditos troggs!", q = 432, a = "C" }, { m = 1426, z = "Dun Morogh", x = 73.7, y = 54.9, n = "Objetivo: El servidor público", q = 433, a = "C" }, { m = 1426, z = "Dun Morogh", x = 69.1, y = 56.3, n = "Entregar: ¡Malditos troggs! (Supervisor Petrocejas)", q = 432, a = "T" }, { m = 1426, z = "Dun Morogh", x = 68.7, y = 56.0, n = "Entregar: El servidor público (Senador Mehr Piedrasanta)", q = 433, a = "T" } } },
      { t = "Complejo Vetaferro, al este de la cantera: mata a los enanos Hierro Negro y abre la Caja fuerte de Vetaferro para [Complejo Vetaferro]. Guarda el mineral: lo entregarás cuando vuelvas a Forjaz a entrenar.", wp = { { m = 1426, z = "Dun Morogh", x = 78.0, y = 62.2, n = "Objetivo: Complejo Vetaferro", q = 1681, a = "C" } } },
      { t = "Cruza el túnel de Algaz hasta Loch Modan.", wp = { { m = 1432, z = "Loch Modan", x = 23.0, y = 74.0, n = "Puesto de control de Loch Modan" } }, comprobar = { llegar = 1432 } },
      { t = "Misión extra para no quedarte corto de nivel: [Recoger ídolos] (nivel 18). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1432, z = "Loch Modan", x = 64.9, y = 66.7, n = "Recoger: Recoger ídolos", q = 297, a = "A" }, { m = 1432, z = "Loch Modan", x = 70.6, y = 64.8, n = "Objetivo: Recoger ídolos", q = 297, a = "C" }, { m = 1432, z = "Loch Modan", x = 64.9, y = 66.7, n = "Entregar: Recoger ídolos", q = 297, a = "T" } } }, -- REFUERZO_97 q=297
    
    
