      { t = "Nivel 12-14: vuela de Thelsamar a Forjaz y entrena con Kelstrum Rompepedras en el Barrio Militar: Abrumar, Grito de batalla (rango 2) y, al 14, Maestría táctica y Grito desmoralizador. En la Gran Herrería entrega el mineral a Tormus Forjahonda ([Complejo Vetaferro]) y elige tu arma ([Armas de hierro gris]). Vuelve en grifo. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1455, z = "Forjaz", x = 67.0, y = 90.2, n = "Kelstrum Rompepedras", npc = 1901 }, { m = 1455, z = "Forjaz", x = 48.6, y = 42.5, n = "Entregar: Complejo Vetaferro (Tormus Forjahonda)", q = 1681, a = "T" }, { m = 1455, z = "Forjaz", x = 48.6, y = 42.5, n = "Recoger: Armas de hierro gris (Tormus Forjahonda)", q = 1682, a = "A" }, { m = 1455, z = "Forjaz", x = 48.6, y = 42.5, n = "Entregar: Armas de hierro gris (Tormus Forjahonda)", q = 1682, a = "T" } } },
      { t = "Cabaña del Errante (este del lago): [La caza de crocoliscos], [La fanfarronada de un cazador] y [Suministros de Bingles] de Bingles Pimpampum.", wp = { { m = 1432, z = "Loch Modan", x = 81.8, y = 61.7, n = "Recoger: La caza de crocoliscos (Marek Coracero)", q = 385, a = "A" }, { m = 1432, z = "Loch Modan", x = 83.5, y = 65.5, n = "Recoger: La fanfarronada de un cazador (Daryl el Jovenzuelo)", q = 257, a = "A" }, { m = 1432, z = "Loch Modan", x = 63.6, y = 47.9, n = "Recoger: Suministros de Bingles (Bingles Pimpampum)", q = 2038, a = "A" } } },
