  {
    titulo = "Los Humedales", min = 23, max = 26,
    entrenar = "Al 24: Ejecutar y Revancha (rango 2); al 26, Cargar (rango 2). Talentos: 24, Maestría táctica mejorada; 25-27, Especialización en armas de dos manos.",
    equipo = "Las misiones del Puerto de Menethil dan botas y pantalones de cuero y malla. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello: raptores y cocodrilos dan <Cuero medio>. Minería: estaño y plata en las colinas. A 125 aprende los rangos expertos en Forjaz (Geofram Dedorroca y Balthus Cazarrocas).",
    pasos = {
      { t = "Usa la piedra de hogar para volver a Thelsamar, sube a la presa del norte y crúzala hasta Los Humedales. Sigue el camino hasta el Puerto de Menethil y activa el vuelo.", wp = { { m = 1437, z = "Los Humedales", x = 9.5, y = 59.7, n = "Vuelo del Puerto de Menethil" } }, comprobar = { vuelo = "Menethil" } },
      { t = "En Menethil acepta [Piel de crocolisco joven], [Zarpas de las profundidades] y [Abriéndose paso entre los mocos].", wp = { { m = 1437, z = "Los Humedales", x = 8.6, y = 55.7, n = "Recoger: Piel de crocolisco joven (James Halloran)", q = 484, a = "A" }, { m = 1437, z = "Los Humedales", x = 8.3, y = 58.6, n = "Recoger: Zarpas de las profundidades (Karl Boran)", q = 279, a = "A" }, { m = 1437, z = "Los Humedales", x = 11.8, y = 58.0, n = "Recoger: Abriéndose paso entre los mocos (Shida)", q = 470, a = "A" } } },
      { t = "Murlocs de la costa norte para [Zarpas de las profundidades].", wp = { { m = 1437, z = "Los Humedales", x = 15.5, y = 40.2, n = "Objetivo: Zarpas de las profundidades", q = 279, a = "C" }, { m = 1437, z = "Los Humedales", x = 8.3, y = 58.6, n = "Entregar: Zarpas de las profundidades (Karl Boran)", q = 279, a = "T" } } },
      { t = "Excavación de Whelgar (centro): [La venganza de Ormer] con raptores.", wp = { { m = 1437, z = "Los Humedales", x = 38.2, y = 50.9, n = "Recoger: La venganza de Ormer (Ormer Trenzaferro)", q = 294, a = "A" }, { m = 1437, z = "Los Humedales", x = 25.3, y = 48.8, n = "Objetivo: La venganza de Ormer", q = 294, a = "C" }, { m = 1437, z = "Los Humedales", x = 38.2, y = 50.9, n = "Entregar: La venganza de Ormer (Ormer Trenzaferro)", q = 294, a = "T" } } },
