      { t = "Tumba de Barbahierro: mocos para [Abriéndose paso entre los mocos].", wp = { { m = 1437, z = "Los Humedales", x = 44.5, y = 25.5, n = "Objetivo: Abriéndose paso entre los mocos", q = 470, a = "C" }, { m = 1437, z = "Los Humedales", x = 11.8, y = 58.0, n = "Entregar: Abriéndose paso entre los mocos (Shida)", q = 470, a = "T" } } },
