  {
    titulo = "La Reyerta y Las Mil Agujas", min = 30, max = 32,
    entrenar = "Al 30 haz [La Reyerta]: aprendes Actitud rabiosa e Interceptar, y con ellas el instructor ya te vende Ira rabiosa (30), Torbellino (36) y Zurrar (38). Talentos: 31-32 Emoción de sangre (Bloodthrill) y 33-37 Maestro de armas (Weaponmaster). Instructor en Kalimdor: Capitán Sempremimbre, en Theramore.",
    equipo = "Las misiones de El Desierto de Sal dan buenas recompensas de malla y cuero. Las placas llegan al 40. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello 150+: <Cuero pesado> de las bestias de Las Mil Agujas. Minería 125-175: hierro y oro en las colinas de Las Mil Agujas y de Tanaris.",
    pasos = {
      { t = "Vuela a Menethil y coge el barco a Theramore (Marjal Revolcafango). Activa el vuelo con Baldruc: muy cerca está tu instructor, Capitán Sempremimbre.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 67.5, y = 51.3, n = "Baldruc", npc = 4321 }, { m = 1445, z = "Marjal Revolcafango", x = 67.9, y = 48.4, n = "Capitán Sempremimbre", npc = 8141 } }, comprobar = { vuelo = "Theramore" } },
      { t = "Desde Theramore ve al oeste por el camino hasta Los Baldíos y sube por la costa hacia el norte: la isla de la Reyerta está frente a la costa, al sur de Trinquete (cruza a nado). Entrega [El isleño] a Klannoc Macleod y acepta [La Reyerta].", wp = { { m = 1413, z = "Los Baldíos", x = 68.6, y = 49.2, n = "Entregar: El isleño (Klannoc Macleod)", q = 1718, a = "T" }, { m = 1413, z = "Los Baldíos", x = 68.6, y = 49.2, n = "Recoger: La Reyerta (Klannoc Macleod)", q = 1719, a = "A" } } },
      { t = "Sube al ring del centro de la isla para empezar [La Reyerta]: vence a los luchadores que salen uno tras otro y al final a Will el Grande. Entrega a Klannoc Macleod: aprendes Actitud rabiosa e Interceptar. Acepta [El Cazavientos]: lo entregarás al 36-39, en las Montañas de Alterac.", wp = { { m = 1413, z = "Los Baldíos", x = 68.6, y = 48.7, n = "Objetivo: La Reyerta", q = 1719, a = "C" }, { m = 1413, z = "Los Baldíos", x = 68.6, y = 49.2, n = "Entregar: La Reyerta (Klannoc Macleod)", q = 1719, a = "T" }, { m = 1413, z = "Los Baldíos", x = 68.6, y = 49.2, n = "Recoger: El Cazavientos (Klannoc Macleod)", q = 1791, a = "A" } } },
      { t = "Desde la isla baja al sur por Los Baldíos hasta el Gran Elevador y sigue al este por Las Mil Agujas hasta El Desierto de Sal.", wp = { { m = 1441, z = "Las Mil Agujas", x = 78.0, y = 77.0, n = "El Desierto de Sal" } }, comprobar = { llegar = 1441 } },
      { t = "Acepta [Veneno de escórpidos salados], [Caparazones endurecidos], [Menos peso], [Piezas de coches cohete] y [Un bache en la carretera].", wp = { { m = 1441, z = "Las Mil Agujas", x = 78.1, y = 77.1, n = "Recoger: Veneno de escórpidos salados (Fizzle Pernolatón)", q = 1104, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 78.1, y = 77.1, n = "Recoger: Caparazones endurecidos (Wizzle Pernolatón)", q = 1105, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 80.2, y = 75.9, n = "Recoger: Menos peso (Pozík)", q = 1176, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 77.8, y = 77.3, n = "Recoger: Piezas de coches cohete (Kravel Karbarbán)", q = 1110, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 81.6, y = 78.0, n = "Recoger: Un bache en la carretera (Maestro rastreador Zherin)", q = 1175, a = "A" } } },
      { t = "Escórpidos, tortugas, buitres y basiliscos alrededor de la pista; las piezas de coche caen de todo.", wp = { { m = 1441, z = "Las Mil Agujas", x = 73.3, y = 71.0, n = "Objetivo: Veneno de escórpidos salados", q = 1104, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 81.6, y = 55.2, n = "Objetivo: Caparazones endurecidos", q = 1105, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 87.9, y = 65.4, n = "Objetivo: Menos peso", q = 1176, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 79.2, y = 87.1, n = "Objetivo: Piezas de coches cohete", q = 1110, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 78.3, y = 88.0, n = "Objetivo: Un bache en la carretera", q = 1175, a = "C" } } },
