      { t = "Nivel 46-48: en el Pico Nidal entrena con Bordolf Axegrim: Cargar (rango 3), Embate (rango 4) y, al 48, Golpe mortal (rango 2), Ejecutar (rango 4) y Golpe heroico (rango 7). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1425, z = "Tierras del Interior", x = 14.4, y = 43.0, n = "Bordolf Axegrim", npc = 270278 } }, comprobar = { hechizos = { 21551 } } },
