R.profesiones = {
  { nombre = "Minería", skill = 186, icono = "Interface\\Icons\\Trade_Mining", intro = "Mina cada veta que veas: da puntos y oro para los entrenamientos. Fundir en una forja también da puntos. Rangos: aprendiz con Messana Crestwind en Shen'dar (Isla Zephras) o con Kelsey Fargo en la entrada de la Mina del Eco (también vende el <Pico de minero>); oficial con Gelman Petramano en el Distrito de los Enanos de Ventormenta o con Geofram Dedorroca en Forjaz (minería 50 y nivel 10); experto y artesano con Geofram Dedorroca (125 y nivel 20; 200 y nivel 25).", pasos = {
